(()=>{const hero=document.querySelector('.hero-section');const bar=document.querySelector('.product-bar');if(!hero||parent===window)return;let hidden=null;const check=()=>{const next=hero.getBoundingClientRect().bottom>(bar?bar.offsetHeight:0)+40;if(next!==hidden){hidden=next;parent.postMessage({namespace:'ctuav-demo',type:'hero-nav',hidden},'*');}};addEventListener('scroll',check,{passive:true});addEventListener('resize',check);addEventListener('message',event=>{if(event.source!==parent||event.data?.namespace!=='ctuav-demo')return;if(event.data.type==='view-active'&&event.data.active){hidden=null;check();}
if(event.data.type==='nav-offset')document.documentElement.style.setProperty('--demo-nav',event.data.px+'px');});check();})();